patch:
diff --git a/repro-no-loss-of-precision.js b/repro-no-loss-of-precision.js
new file mode 100644
index 0000000..047b565
--- /dev/null
+++ b/repro-no-loss-of-precision.js
@@ -0,0 +1,37 @@
+"use strict";
+
+// Repro for: no-loss-of-precision flags 9.000e+3 (a value that is exactly representable).
+// Run from the repo root: node repro-no-loss-of-precision.js
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const literals = [
+	"9.000e+3", // reported
+	"9.000e3", // from triage comment (error)
+	"9.0000e4", // from triage comment (error)
+	"9.000e4", // ok
+	"9.0000e5", // ok
+	"9000", // control
+	"1.0e1", // smallest trigger found: trailing zero in coefficient, exponent == digits - 1
+	"9.0e3", // control: exponent >= digits, toPrecision uses exponential form
+	"1.50e1", // control: exponent < digits - 1, toPrecision keeps a decimal point
+];
+
+let failures = 0;
+
+for (const literal of literals) {
+	const messages = linter.verify(`const x = ${literal};`, {
+		rules: { "no-loss-of-precision": "error" },
+	});
+	const flagged = messages.length > 0;
+	// Every literal here is exactly representable as a double, so none should be flagged.
+	console.log(
+		`${literal.padEnd(10)} value=${String(Number(literal)).padEnd(6)} ${flagged ? "FLAGGED (bug)" : "ok"}`,
+	);
+	if (flagged) {
+		failures++;
+	}
+}
+
+console.log(`\n${failures} of ${literals.length} exactly-representable literals wrongly flagged`);
+process.exitCode = failures ? 1 : 0;
